 const list=componentList(),index=selected?list.indexOf(selected):-1;
 $('part-position').textContent=selected?(index<0?'Component hidden by current filters':`${index+1} of ${list.length.toLocaleString()} in ${EQUIPMENT[selectedEquipmentId].tag}`):'';
 $('previous').disabled=$('next').disabled=list.length<2;
 $('inspect-components').disabled=!list.length;
