async function takeSectionPhoto(){
 if(photoRendering||!section.enabled||!sectionSlice||section.fraction>=1)throw Error('Create a visible section before taking a photo.');
 photoRendering=true;
 const shotCamera=camera.clone(),identity=sectionPhotoIdentity({tag:section.scope==='equipment'?EQUIPMENT[section.equipmentId]?.tag:'Visible plant',axis:section.axis,value:sectionSlice.value,flip:section.flip,normal:sectionPlane.normal[section.axis],configuration:(designSelection.scope==='future'?'Archived concept':A160_DESIGNS[designSelection.a160].short)+' · draft'});
 try{
  await new Promise(resolve=>requestAnimationFrame(resolve));
  if(dirty)updateParts();sectionInspector.draw();
  const capture=captureSectionPhoto({renderer,scene,camera:shotCamera,helpers:[selectionBox,equipmentBox,clashBox,exploration?.lines],identity});
  photoRendering=false;const result=await capture;downloadSectionPhoto(result);return result;
 }finally{photoRendering=false;}
}


// Browse plant owns a temporary assembled view and a separate eye-level camera.
// Existing orbit, section, journey and traffic tools resume through one restore path.
let browsePreviewHelpers=[];
function setBrowseCleanPreview(value){if(value){browsePreviewHelpers=[grid,selectionBox,equipmentBox,clashBox,exploration?.lines].filter(Boolean).map(node=>[node,node.visible]);for(const [node]of browsePreviewHelpers)node.visible=false;}else{for(const [node,visible]of browsePreviewHelpers)node.visible=visible;browsePreviewHelpers=[];}}
async function takeBrowsePhoto({camera:shotCamera,helpers}){
 if(photoRendering)throw Error('An image is already being prepared.');photoRendering=true;
 try{if(dirty)updateParts();const stamp=new Date().toISOString().replace(/[:.]/g,'-');const capture=captureSectionPhoto({renderer,scene,camera:shotCamera,helpers:[...helpers,grid,selectionBox,equipmentBox,clashBox,exploration?.lines],identity:{filename:`rGO_BrowsePlant_v130_${stamp}.png`},maxEdge:4096,maxPixels:16000000,includeFooter:false});photoRendering=false;const result=await capture;downloadSectionPhoto(result);return result;}finally{photoRendering=false;}
}
async function takeHighQualityPhoto({resolution,format,background}){
 if(photoRendering)throw Error('An image is already being prepared.');
 if(plantBrowse?.active)throw Error('Use High-quality photo in the Browse Plant panel to preserve the walking camera.');
 photoRendering=true;const shotCamera=camera.clone(),stamp=new Date().toISOString().replace(/[:.]/g,'-'),style=mode==='studio'?'Studio':'Engineering';
 const cleanBackground=background==='clean'?(mode==='studio'?'#111d2b':'#e8eef2'):null;
 try{if(dirty)updateParts();renderer.shadowMap.needsUpdate=true;await new Promise(resolve=>requestAnimationFrame(resolve));
  const result=await captureSectionPhoto({renderer,scene,camera:shotCamera,helpers:[grid,selectionBox,equipmentBox,clashBox,exploration?.lines],identity:{filename:`rGO_${style}_${stamp}.${format==='jpeg'?'jpg':'png'}`},maxEdge:resolution,maxPixels:resolution>=4096?16000000:6000000,includeFooter:false,format,background:cleanBackground});downloadSectionPhoto(result);return result;
 }finally{photoRendering=false;}
}
mountPhotoCapture({button:$('take-photo'),dialog:$('photo-capture-dialog'),getMode:()=>mode,onCapture:takeHighQualityPhoto});
